// Ugoira assembly. Archives are built in the test from generated bytes; no real Pixiv data.

/// Writes a minimal ZIP (stored, or compressed by `compress` when given) the way Ugoira archives look.
func makeZip(_ files: [(name: String, bytes: [UInt8])], compress: (([UInt8]) -> [UInt8]?)? = nil) -> Data {
    var out: [UInt8] = [], central: [UInt8] = []
    func le16(_ v: Int) -> [UInt8] { [UInt8(v & 0xff), UInt8(v >> 8 & 0xff)] }
    func le32(_ v: Int) -> [UInt8] { [UInt8(v & 0xff), UInt8(v >> 8 & 0xff), UInt8(v >> 16 & 0xff), UInt8(v >> 24 & 0xff)] }
    for file in files {
        let name = Array(file.name.utf8)
        let packed = compress?(file.bytes)
        let method = packed == nil ? 0 : 8
        let body = packed ?? file.bytes
        let crc = Int(CRC32.checksum(file.bytes))
        let offset = out.count
        out += le32(0x0403_4b50) + le16(20) + le16(0) + le16(method) + le16(0) + le16(0)
        out += le32(crc) + le32(body.count) + le32(file.bytes.count) + le16(name.count) + le16(0) + name + body
        central += le32(0x0201_4b50) + le16(20) + le16(20) + le16(0) + le16(method) + le16(0) + le16(0)
        central += le32(crc) + le32(body.count) + le32(file.bytes.count) + le16(name.count) + le16(0) + le16(0)
        central += le16(0) + le16(0) + le32(0) + le32(offset) + name
    }
    let centralOffset = out.count
    out += central
    out += le32(0x0605_4b50) + le16(0) + le16(0) + le16(files.count) + le16(files.count)
    out += le32(central.count) + le32(centralOffset) + le16(0)
    return Data(out)
}

struct UgoiraTimingTests {
    @Test func wholeTenMillisecondDelaysAreExact() {
        #expect(UgoiraTiming.centiseconds([100, 100, 250]) == [10, 10, 25])
    }

    @Test func oddDelaysFollowTheTimelineAndKeepTheTotal() {
        #expect(UgoiraTiming.centiseconds([33, 67]) == [3, 7])
        #expect(UgoiraTiming.centiseconds([33, 33, 34]) == [3, 4, 3])
        // Every frame within 5 ms of its true end time, total exact, for typical 20 ms+ delays.
        var generator = SplitMix64(seed: 7)
        let delays = (0..<200).map { _ in 20 + Int(generator.next() % 180) }
        let result = UgoiraTiming.centiseconds(delays)
        var trueEnd = 0, gifEnd = 0
        for (ms, cs) in zip(delays, result) {
            trueEnd += ms; gifEnd += cs * 10
            #expect(abs(gifEnd - trueEnd) <= 5)
        }
        #expect(abs(result.reduce(0, +) * 10 - delays.reduce(0, +)) <= 5)
    }

    @Test func tooFastFramesGetTheGIFMinimum() {
        #expect(UgoiraTiming.centiseconds([10, 10, 10, 10]).allSatisfy { $0 >= 2 })
    }
}

struct ZipArchiveTests {
    @Test func crcMatchesTheStandardCheckValue() {
        #expect(CRC32.checksum(Array("123456789".utf8)) == 0xCBF4_3926)
    }

    @Test func storedEntriesAreReadAndVerified() throws {
        let files: [(name: String, bytes: [UInt8])] = [("000000.jpg", [1, 2, 3]), ("000001.jpg", [4, 5])]
        let archive = try ZipArchive(makeZip(files))
        #expect(Set(archive.entries.keys) == ["000000.jpg", "000001.jpg"])
        #expect(try archive.extract("000001.jpg", maxBytes: 10) == Data([4, 5]))
        #expect(throws: MediaError.parsingChanged) { try archive.extract("missing.jpg", maxBytes: 10) }
        #expect(throws: MediaError.resourceLimitExceeded) { try archive.extract("000000.jpg", maxBytes: 2) }
    }

    @Test func damagedOrForeignDataIsRejected() throws {
        let file: [(name: String, bytes: [UInt8])] = [("a.jpg", [9, 9, 9, 9])]
        var bytes = [UInt8](makeZip(file))
        bytes[35] ^= 0xff // first payload byte: 30-byte local header + 5-byte name
        let archive = try ZipArchive(Data(bytes))
        #expect(throws: MediaError.integrityMismatch) { try archive.extract("a.jpg", maxBytes: 10) }
        #expect(throws: MediaError.unsupportedFormat) { try ZipArchive(Data("not a zip archive at all, really".utf8)) }
    }
}

#if canImport(ImageIO) && canImport(Compression)
import CoreGraphics
import ImageIO

private func framePNG(_ r: CGFloat, _ g: CGFloat, _ b: CGFloat) throws -> [UInt8] {
    let context = try #require(CGContext(data: nil, width: 8, height: 6, bitsPerComponent: 8, bytesPerRow: 0,
                                         space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                         bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue))
    context.setFillColor(CGColor(srgbRed: r, green: g, blue: b, alpha: 1))
    context.fill(CGRect(x: 0, y: 0, width: 8, height: 6))
    let output = NSMutableData()
    let destination = try #require(CGImageDestinationCreateWithData(output as CFMutableData, "public.png" as CFString, 1, nil))
    CGImageDestinationAddImage(destination, try #require(context.makeImage()), nil)
    #expect(CGImageDestinationFinalize(destination))
    return [UInt8](output as Data)
}

private func deflate(_ input: [UInt8]) -> [UInt8]? {
    var output = [UInt8](repeating: 0, count: input.count + 1024)
    let written = input.withUnsafeBufferPointer { source in
        output.withUnsafeMutableBufferPointer { destination in
            compression_encode_buffer(destination.baseAddress!, destination.count, source.baseAddress!, source.count, nil, COMPRESSION_ZLIB)
        }
    }
    return written > 0 ? Array(output.prefix(written)) : nil
}

struct UgoiraAssemblerTests {
    private func job(_ zip: Data, frames: [(String, Int)], in directory: URL) throws -> AssemblyJob {
        let archive = directory.appendingPathComponent("frames.zip")
        try zip.write(to: archive)
        return AssemblyJob(assembly: .ugoiraToGIF(keepOriginalArchive: false), inputs: [archive],
                           ugoiraFrames: try frames.map { try UgoiraFrame(file: $0.0, delayMilliseconds: $0.1) },
                           outputDirectory: directory, maxOutputBytes: 10_000_000)
    }

    @Test(arguments: [false, true])
    func archiveBecomesGIFWithOrderAndRoundedTimeline(compressed: Bool) async throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("ugoira-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let red = try framePNG(1, 0, 0), green = try framePNG(0, 1, 0), blue = try framePNG(0, 0, 1)
        let entries: [(name: String, bytes: [UInt8])] = [("000000.png", red), ("000001.png", green), ("000002.png", blue)]
        let packer: (([UInt8]) -> [UInt8]?)? = compressed ? deflate : nil
        let zip = makeZip(entries, compress: packer)
        let frames: [(String, Int)] = [("000000.png", 33), ("000001.png", 67), ("000002.png", 100)]
        let request = try job(zip, frames: frames, in: directory)
        let result = try await UgoiraAssembler().assemble(request)
        #expect(result.fileExtension == "gif")
        #expect(result.file.deletingLastPathComponent().standardizedFileURL == directory.standardizedFileURL)
        let summary = try #require(GIFInspector.inspect(result.file))
        #expect(summary == GIFInspector.Summary(frameCount: 3, delaysCentiseconds: [3, 7, 10], width: 8, height: 6))
        let source = try #require(CGImageSourceCreateWithURL(result.file as CFURL, nil))
        let first = try #require(CGImageSourceCreateImageAtIndex(source, 0, nil))
        let last = try #require(CGImageSourceCreateImageAtIndex(source, 2, nil))
        #expect(first.width == 8 && last.height == 6)
    }

    @Test func missingFrameOrWrongJobFails() async throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("ugoira-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let only: [(name: String, bytes: [UInt8])] = [("000000.png", try framePNG(1, 0, 0))]
        let zip = makeZip(only)
        let missing: [(String, Int)] = [("000000.png", 50), ("000009.png", 50)]
        let request = try job(zip, frames: missing, in: directory)
        do {
            _ = try await UgoiraAssembler().assemble(request)
            Issue.record("expected failure")
        } catch { #expect(error == .parsingChanged) }
        let files = try FileManager.default.contentsOfDirectory(atPath: directory.path).filter { $0.hasSuffix(".gif") }
        #expect(files.isEmpty, "\(files)")
        let passthrough = AssemblyJob(assembly: .passthrough, inputs: [], ugoiraFrames: [], outputDirectory: directory, maxOutputBytes: 1)
        do { _ = try await UgoiraAssembler().assemble(passthrough); Issue.record("expected failure") }
        catch { #expect(error == .unsupportedFormat) }
    }
}
#endif
